<script setup lang="ts">
import Icon from '../Icon.vue'
import { computed,onBeforeUnmount,reactive,ref,watch } from 'vue'
import { onBeforeRouteLeave,onBeforeRouteUpdate,useRoute,useRouter } from 'vue-router'
import { useSettingsScope } from '../settingsScope'
const { request:api }=useSettingsScope()
import { t,formatDate } from '../../i18n'
import { testingEditable,testPositiveID,testTone,type TestWorkspace,type TestCaseRecord } from '../../testingWorkspace'
import { useWorkspaceStore } from '../../stores/workspace'
import AppSelect from '../AppSelect.vue'
import DatePicker from '../DatePicker.vue'
import MemberMultiSelect from '../MemberMultiSelect.vue'
import QualityComments from '../QualityComments.vue'
import ResizableDrawer from '../ResizableDrawer.vue'
const props=defineProps<{tab:string;workspace:TestWorkspace;plans:any[];executions:any[];members:any[];sprints:any[]}>(),emit=defineEmits<{refresh:[]}>()
const route=useRoute(),router=useRouter(),session=useWorkspaceStore()
const writable=computed(()=>props.workspace.canEdit&&!session.operationDisabled&&!session.identityConflict)
const q=ref(''),status=ref(''),planFilter=ref(0),executor=ref(''),page=ref(1),pageSize=ref(20),saving=ref(false),loading=ref(false),error=ref(''),notice=ref('')
const filteredExecutions=computed(()=>props.executions.filter(x=>(!planFilter.value||x.planId===planFilter.value)&&(!status.value||x.status===status.value)&&(!executor.value||x.executorUserId===executor.value)&&(!q.value||`${x.caseTitle} ${x.planName} ${x.actualResult}`.toLowerCase().includes(q.value.trim().toLowerCase()))))
const reportRows=computed(()=>props.executions.filter(x=>!planFilter.value||x.planId===planFilter.value))
const distribution=computed(()=>['未执行','通过','失败','阻塞','跳过'].map(name=>({name,count:reportRows.value.filter(x=>x.status===name).length})))
const resultCount=(name:string)=>distribution.value.find(x=>x.name===name)?.count||0
const total=computed(()=>reportRows.value.length), executed=computed(()=>resultCount('通过')+resultCount('失败')+resultCount('阻塞')+resultCount('跳过'))
// 通过率只比较已判定的通过/失败；阻塞和跳过不应美化质量指标。
const assessed=computed(()=>resultCount('通过')+resultCount('失败'))
const maxPage=computed(()=>Math.max(1,Math.ceil(filteredExecutions.value.length/pageSize.value)))
const visibleExecutions=computed(()=>filteredExecutions.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value))
watch([q,status,planFilter,executor,pageSize],()=>{page.value=1})
watch(()=>route.query.planFilter,value=>{planFilter.value=testPositiveID(value)||0},{immediate:true})
watch(maxPage,()=>{if(page.value>maxPage.value)page.value=maxPage.value})
const filteredPlans=computed(()=>props.plans.filter(x=>!q.value||`${x.name} ${x.code} ${x.scope}`.toLowerCase().includes(q.value.trim().toLowerCase())))
const planOptions=computed(()=>[{value:0,label:t('全部计划')},...props.plans.map(x=>({value:x.id,label:x.name}))])
const executorOptions=computed(()=>[{value:'',label:t('所有执行人')},...props.members.filter(x=>x.active).map(x=>({value:x.id,label:x.name}))])
const stateOptions=computed(()=>['未执行','通过','失败',...(props.workspace.settings.blockedEnabled||execution.value?.status==='阻塞'?['阻塞']:[]),'跳过'].map(value=>({value,label:t(value)})))
const ownerName=(id:string)=>props.members.find(x=>x.id===id)?.name||''
const plan=ref<any>(null),showPlan=ref(false),execution=ref<any>(null),caseDetail=ref<TestCaseRecord|null>(null),history=ref<any[]>([]),width=ref(1080)
const freshPlan=()=>({name:'',sprint:'待规划',version:'',scope:'',owner:'',ownerUserId:'',environment:'',executorUserId:'',startDate:'',endDate:'',status:'规划中',caseIds:[] as number[]})
const planEdit=reactive(freshPlan()),result=reactive({status:'未执行',actualResult:'',note:''}),baseline=ref(''),dateStartValid=ref(true),dateEndValid=ref(true)
const commentsPanel=ref<InstanceType<typeof QualityComments>|null>(null)
const dirty=computed(()=>showPlan.value?JSON.stringify(planEdit)!==baseline.value:execution.value?JSON.stringify(result)!==baseline.value:false)
function canLeave(){return !saving.value&&commentsPanel.value?.canLeave()!==false&&(!dirty.value||window.confirm(t('尚有未保存的修改，确定离开吗？')))}
onBeforeRouteLeave(canLeave);onBeforeRouteUpdate((to,from)=>JSON.stringify(to.query)===JSON.stringify(from.query)||canLeave())
function unload(event:BeforeUnloadEvent){if(dirty.value||saving.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',unload)
let detailVersion=0,candidateVersion=0
onBeforeUnmount(()=>{detailVersion++;candidateVersion++;window.removeEventListener('beforeunload',unload)})
// 新建草稿使尚未返回的详情请求失效，避免旧计划覆盖当前输入。
function createPlan(){if(!canLeave())return;detailVersion++;loading.value=false;caseQ.value='';candidatePage.value=1;dateStartValid.value=true;dateEndValid.value=true;plan.value=null;execution.value=null;Object.assign(planEdit,freshPlan());baseline.value=JSON.stringify(planEdit);showPlan.value=true;error.value='';void searchCases()}
async function openPlan(id:number){await router.replace({query:{tab:'plans',plan:id}})}
async function openExecution(item:any){await router.replace({query:{tab:'executions',execution:item.id}})}
async function applyRoute(){
 const sequence=++detailVersion;error.value='';showPlan.value=false;execution.value=null;caseDetail.value=null;history.value=[]
 const id=testPositiveID(route.query.plan),eid=testPositiveID(route.query.execution)
 if(!id&&!eid){loading.value=false;return}loading.value=true
 try{
  if(id){const value=await api<any>(`/test-plans/${id}`);if(sequence!==detailVersion)return;plan.value=value;Object.assign(planEdit,testingEditable(freshPlan(),value));baseline.value=JSON.stringify(planEdit);showPlan.value=true;void searchCases()}
  else {const value=props.executions.find(x=>x.id===eid);if(!value)throw Error('执行记录不存在或无权访问');execution.value=value;Object.assign(result,{status:value.status,actualResult:value.actualResult||'',note:value.note||''});baseline.value=JSON.stringify(result)
   const [caseResult,historyResult]=await Promise.allSettled([api<TestCaseRecord>(`/test-cases/${value.caseId}`),api<{items:any[]}>(`/test-executions/${value.id}/history`)]);if(sequence!==detailVersion)return
   if(caseResult.status==='fulfilled')caseDetail.value=caseResult.value;else throw caseResult.reason
   if(historyResult.status==='fulfilled')history.value=historyResult.value.items;else throw historyResult.reason
  }
 }catch(cause){if(sequence===detailVersion)error.value=cause instanceof Error?cause.message:'加载失败，请重试'}finally{if(sequence===detailVersion)loading.value=false}
}
watch(()=>route.query,applyRoute,{immediate:true})
async function closeDetail(){if(!canLeave())return;showPlan.value=false;execution.value=null;await router.replace({query:{tab:props.tab}})}
async function savePlan(){if(saving.value||!writable.value||!dateStartValid.value||!dateEndValid.value)return;saving.value=true;error.value=''
 try{const body=testingEditable(freshPlan(),planEdit);if(plan.value)delete (body as any).caseIds;await api(plan.value?`/test-plans/${plan.value.id}`:'/test-plans',{method:plan.value?'PATCH':'POST',body:JSON.stringify(body)});baseline.value=JSON.stringify(planEdit);showPlan.value=false;emit('refresh');notice.value='测试计划已保存';saving.value=false;await router.replace({query:{tab:'plans'}})}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败，请重试'}finally{saving.value=false}}
async function execute(){if(!execution.value||saving.value||!writable.value)return;if(['失败','阻塞'].includes(result.status)&&!result.actualResult.trim()){error.value='失败或阻塞时请填写实际结果，便于定位问题';return}saving.value=true;error.value=''
 try{await api(`/test-executions/${execution.value.id}`,{method:'PATCH',body:JSON.stringify(result)});execution.value={...execution.value,...result};baseline.value=JSON.stringify(result);history.value=(await api<{items:any[]}>(`/test-executions/${execution.value.id}/history`)).items;notice.value='执行结果已保存。';emit('refresh')}catch(cause){error.value=cause instanceof Error?cause.message:'执行结果保存失败'}finally{saving.value=false}}
async function toDefect(item:any){if(saving.value||!writable.value||dirty.value)return;saving.value=true;error.value='';try{const defect=await api<any>(`/test-executions/${item.id}/create-defect`,{method:'POST'});if(execution.value?.id===item.id)execution.value={...execution.value,defectId:defect.id};notice.value=t('已生成 {code}，执行记录已建立关联。',{code:defect.code});emit('refresh')}catch(cause){error.value=cause instanceof Error?cause.message:'缺陷生成失败'}finally{saving.value=false}}
const caseQ=ref(''),candidatePage=ref(1),candidateTotal=ref(0),candidates=ref<TestCaseRecord[]>([]),candidateLoading=ref(false)
async function searchCases(){const sequence=++candidateVersion;candidateLoading.value=true;try{const data=await api<{items:TestCaseRecord[];total:number}>('/test-cases?'+new URLSearchParams({q:caseQ.value,status:'已通过',page:String(candidatePage.value),pageSize:'20'}));if(sequence===candidateVersion){candidates.value=data.items.filter(x=>x.enabled);candidateTotal.value=data.total}}catch(cause){if(sequence===candidateVersion)error.value=cause instanceof Error?cause.message:'用例读取失败'}finally{if(sequence===candidateVersion)candidateLoading.value=false}}
function toggleCase(id:number){planEdit.caseIds=planEdit.caseIds.includes(id)?planEdit.caseIds.filter(x=>x!==id):[...planEdit.caseIds,id]}
</script>

<template>
 <section class="test-operations">
  <header class="test-section-head"><div><h2>{{t(tab==='plans'?'测试计划':tab==='executions'?'测试执行':'质量报告')}}</h2><p>{{t(tab==='plans'?'按版本和迭代组织测试范围，明确执行人、环境与时间。':tab==='executions'?'查看用例步骤，记录实际结果；失败项可直接生成并追溯缺陷。':'按测试计划汇总当前执行结果，跳过和阻塞不会计为通过。')}}</p></div><button v-if="tab==='plans'" class="btn primary" :disabled="!writable" @click="createPlan">＋ {{t('创建测试计划')}}</button></header>
  <p v-if="error&&!showPlan&&!execution" class="test-notice error" role="alert">{{t(error)}}</p><p v-if="notice" class="test-notice success" role="status">{{t(notice)}}</p>
  <div class="test-filter-row"><label v-if="tab!=='report'" class="test-search"><Icon name="search"/><input v-model="q" :aria-label="t('搜索计划或用例')" :placeholder="t('搜索计划或用例')"></label><template v-if="tab!=='plans'"><AppSelect v-model="planFilter" :options="planOptions" :label="t('测试计划')"/><template v-if="tab==='executions'"><AppSelect v-model="status" :options="[{value:'',label:t('全部状态')},...['未执行','通过','失败','阻塞','跳过'].map(value=>({value,label:t(value)}))]" :label="t('执行状态')"/><AppSelect v-model="executor" :options="executorOptions" :label="t('执行人')"/><button class="btn" :class="{primary:executor===session.currentUser?.id}" @click="executor=executor===session.currentUser?.id?'':session.currentUser?.id||''">{{t('我执行的')}}</button></template></template></div>
  <div v-if="tab==='plans'" class="test-plans-grid"><article v-for="item in filteredPlans" :key="item.id" class="test-plan-card"><header><span class="test-code">{{item.code}}</span><span class="test-badge neutral">{{t(item.status)}}</span></header><button class="test-text-button" @click="openPlan(item.id)">{{item.name}}</button><p>{{item.scope||t('未填写测试范围')}}</p><dl><div><dt>{{t('环境')}}</dt><dd>{{item.environment||'—'}}</dd></div><div><dt>{{t('执行人')}}</dt><dd>{{ownerName(item.executorUserId)||t('待安排')}}</dd></div><div><dt>{{t('日期')}}</dt><dd>{{item.startDate||'—'}} → {{item.endDate||'—'}}</dd></div></dl><div class="test-progress"><span :style="{width:(item.total?item.executed/item.total*100:0)+'%'}"/></div><footer><span>{{item.executed||0}} / {{item.total||0}} {{t('已执行')}}</span><router-link :to="`/tests?tab=executions&planFilter=${item.id}`">{{t('查看执行')}} →</router-link></footer></article><div v-if="!filteredPlans.length" class="test-empty-cell"><h3>{{t('尚无测试计划')}}</h3><p>{{t('选择用例并安排执行，开始一次版本验证。')}}</p></div></div>
  <template v-else-if="tab==='executions'"><div class="test-table-wrap"><table class="test-table"><thead><tr><th>{{t('测试用例')}}</th><th>{{t('计划')}}</th><th>{{t('执行状态')}}</th><th>{{t('执行人')}}</th><th>{{t('实际结果')}}</th><th>{{t('执行时间')}}</th><th>{{t('缺陷')}}</th></tr></thead><tbody><tr v-for="item in visibleExecutions" :key="item.id"><td class="test-title-cell"><button class="test-text-button" @click="openExecution(item)">{{item.caseTitle}}</button><small>EXE-{{String(item.id).padStart(4,'0')}}</small></td><td>{{item.planName}}</td><td><span :class="['test-badge',testTone(item.status)]">{{t(item.status)}}</span></td><td>{{item.executor||ownerName(item.executorUserId)||t('待执行')}}</td><td class="test-ellipsis" :title="item.actualResult">{{item.actualResult||'—'}}</td><td>{{formatDate(item.executedAt)}}</td><td><router-link v-if="item.defectId" :to="`/defects?bug=${item.defectId}`">BUG-{{String(item.defectId).padStart(4,'0')}}</router-link><button v-else-if="item.status==='失败'" class="test-text-button danger" :disabled="saving||!writable" @click="toDefect(item)">{{t('生成缺陷')}}</button><span v-else>—</span></td></tr><tr v-if="!visibleExecutions.length"><td colspan="7" class="test-empty-cell">{{t('暂无符合条件的执行记录')}}</td></tr></tbody></table></div><footer class="test-pagination"><span>{{t('共 {count} 条',{count:filteredExecutions.length})}}</span><div><AppSelect v-model="pageSize" :label="t('每页条数')" :options="[20,50,100].map(value=>({value,label:String(value)}))"/><button :disabled="page<=1" class="test-page-button" :aria-label="t('上一页')" @click="page--">‹</button><span>{{page}} / {{maxPage}}</span><button :disabled="page>=maxPage" class="test-page-button" :aria-label="t('下一页')" @click="page++">›</button></div></footer></template>
  <template v-else><div class="test-metrics"><article><span>{{t('计划执行项')}}</span><b>{{total}}</b><small>{{t('同一用例在不同计划中分别计数')}}</small></article><article><span>{{t('执行率')}}</span><b>{{total?Math.round(executed/total*100):0}}%</b><small>{{executed}} / {{total}} {{t('已有执行结论')}}</small></article><article><span>{{t('已判定通过率')}}</span><b>{{assessed?Math.round(resultCount('通过')/assessed*100)+'%':'—'}}</b><small>{{t('通过 /（通过 + 失败）')}}</small></article><article><span>{{t('待关注')}}</span><b>{{resultCount('失败')+resultCount('阻塞')}}</b><small>{{t('失败与阻塞执行项')}}</small></article></div><div class="test-report-card"><h3>{{t('执行结果分布')}}</h3><p class="test-muted">{{t('各项比例统一以当前范围内的全部执行项为分母。')}}</p><div v-for="entry in distribution" :key="entry.name" class="test-distribution"><span :class="['test-badge',testTone(entry.name)]">{{t(entry.name)}}</span><div class="test-progress"><span :class="testTone(entry.name)" :style="{width:(total?entry.count/total*100:0)+'%'}"/></div><b>{{entry.count}}</b><small>{{total?Math.round(entry.count/total*100):0}}%</small></div></div><div class="test-table-wrap"><table class="test-table"><thead><tr><th>{{t('计划质量概览')}}</th><th>{{t('总计')}}</th><th>{{t('已执行')}}</th><th>{{t('通过')}}</th><th>{{t('失败')}}</th><th>{{t('阻塞')}}</th></tr></thead><tbody><tr v-for="item in plans.filter(x=>!planFilter||x.id===planFilter)" :key="item.id"><td><button class="test-text-button" @click="openPlan(item.id)">{{item.name}}</button></td><td>{{item.total||0}}</td><td>{{item.executed||0}}</td><td>{{item.passed||0}}</td><td>{{item.failed||0}}</td><td>{{item.blocked||0}}</td></tr></tbody></table></div></template>
  <div v-if="showPlan" class="drawer-shade" @click.self="closeDetail"><ResizableDrawer v-model:width="width" storage-key="testing.plan.width" :initial-width="1000" :min-width="640" :label="plan?.name||t('创建测试计划')" class="test-plan-drawer"><header class="test-drawer-header"><h2>{{plan?.name||t('创建测试计划')}}</h2><button :disabled="saving" class="test-icon-button" :aria-label="t('关闭')" @click="closeDetail">×</button></header><form class="test-scroll-form" @submit.prevent="savePlan"><div class="test-detail-content"><p v-if="error" class="test-notice error" role="alert">{{t(error)}}</p><fieldset class="test-fieldset" :disabled="saving||!writable"><label class="test-field">{{t('计划名称')}} *<input v-model="planEdit.name" maxlength="200" required></label><label class="test-field">{{t('测试范围')}}<textarea v-model="planEdit.scope" rows="3" maxlength="20000"/></label><div class="test-two-columns"><label class="test-field">{{t('迭代')}}<AppSelect v-model="planEdit.sprint" :label="t('迭代')" :disabled="saving||!writable" :options="[...new Set(['待规划',...sprints.filter(x=>['规划中','进行中'].includes(x.status)).map(x=>x.name),planEdit.sprint])].map(value=>({value,label:value==='待规划'?t(value):value}))"/></label><label class="test-field">{{t('版本号')}}<input v-model="planEdit.version" maxlength="100"></label><label class="test-field">{{t('测试环境')}}<input v-model="planEdit.environment" maxlength="500" :placeholder="t('例如：预发布环境 / Chrome')"></label><label class="test-field">{{t('计划状态')}}<AppSelect v-model="planEdit.status" :disabled="saving||!writable" :label="t('计划状态')" :options="['规划中','执行中','已完成','已取消'].map(value=>({value,label:t(value)}))"/></label><MemberMultiSelect single :label="t('计划负责人')" :model-value="planEdit.ownerUserId?[planEdit.ownerUserId]:[]" :legacy-name="planEdit.owner" :members="members" :show-lead="false" :disabled="saving||!writable" @update:model-value="planEdit.ownerUserId=$event[0]||'';planEdit.owner=ownerName($event[0]||'')"/><MemberMultiSelect single :label="t('执行人')" :model-value="planEdit.executorUserId?[planEdit.executorUserId]:[]" :members="members" :show-lead="false" :disabled="saving||!writable" @update:model-value="planEdit.executorUserId=$event[0]||''"/><label class="test-field"><span>{{t('计划开始')}}</span><DatePicker v-model="planEdit.startDate" :label="t('计划开始')" :disabled="saving||!writable" @validity-change="dateStartValid=$event"/></label><label class="test-field"><span>{{t('计划结束')}}</span><DatePicker v-model="planEdit.endDate" :label="t('计划结束')" :disabled="saving||!writable" @validity-change="dateEndValid=$event"/></label></div>
   <template v-if="!plan"><div class="test-section-title"><h3>{{t('选择测试用例')}}</h3><span>{{t('已选 {count} 条',{count:planEdit.caseIds.length})}}</span></div><p class="test-muted">{{t('推荐使用已评审通过且启用的用例。选择跨页保留；计划创建后执行历史不会被覆盖。')}}</p><div class="test-filter-row"><input v-model="caseQ" :aria-label="t('搜索用例')" :placeholder="t('搜索用例编号或标题')" @keydown.enter.prevent="candidatePage=1;searchCases()"><button class="btn" type="button" @click="candidatePage=1;searchCases()">{{t('搜索')}}</button></div><div class="test-case-choices"><label v-for="item in candidates" :key="item.id"><input type="checkbox" :checked="planEdit.caseIds.includes(item.id)" @change="toggleCase(item.id)"><span class="test-code">{{item.code}}</span><b>{{item.title}}</b><span>{{item.priority}}</span></label><p v-if="!candidates.length">{{candidateLoading?t('正在加载…'):t('暂无已评审通过的启用用例，请先完善用例并完成评审。')}}</p></div><div class="test-pagination"><span>{{t('共 {count} 条',{count:candidateTotal})}}</span><div><button type="button" class="test-page-button" :disabled="candidateLoading||candidatePage<=1" @click="candidatePage--;searchCases()">‹</button><span>{{candidatePage}} / {{Math.max(1,Math.ceil(candidateTotal/20))}}</span><button type="button" class="test-page-button" :disabled="candidateLoading||candidatePage*20>=candidateTotal" @click="candidatePage++;searchCases()">›</button></div></div></template><div v-else><h3>{{t('关联用例')}}</h3><div class="test-linked-cases"><router-link v-for="id in planEdit.caseIds" :key="id" :to="`/tests?tab=cases&case=${id}`">TC-{{String(id).padStart(4,'0')}}</router-link></div><p class="test-muted">{{t('已有计划的用例集合保留。需要验证新的范围时请创建新计划。')}}</p></div></fieldset><QualityComments v-if="plan" ref="commentsPanel" :key="'plan-'+plan.id" resource="test-plans" :object-id="plan.id" :members="members" :disabled="saving"/></div><footer class="test-editor-footer"><span>{{dirty?t('有未保存的修改'):t('内容已同步')}}</span><div><button type="button" class="btn" :disabled="saving" @click="closeDetail">{{t('取消')}}</button><button class="btn primary" :disabled="saving||!writable||!dateStartValid||!dateEndValid||(!plan&&!planEdit.caseIds.length)">{{saving?t('保存中…'):t('保存计划')}}</button></div></footer></form></ResizableDrawer></div>
  <div v-if="execution" class="drawer-shade" @click.self="closeDetail"><ResizableDrawer v-model:width="width" storage-key="testing.execution.width" :initial-width="1080" :min-width="680" :label="execution.caseTitle" class="test-execution-drawer"><header class="test-drawer-header"><div><span class="test-breadcrumb">{{execution.planName}} · EXE-{{String(execution.id).padStart(4,'0')}}</span><h2>{{execution.caseTitle}}</h2></div><button class="test-icon-button" :disabled="saving" :aria-label="t('关闭')" @click="closeDetail">×</button></header><div class="test-detail-content"><p v-if="loading">{{t('正在加载…')}}</p><p v-if="error" class="test-notice error" role="alert">{{t(error)}}</p><template v-if="caseDetail"><p class="test-info">{{t('以下为当前用例内容；历史执行结论保存在下方执行历史中。')}}</p><h3>{{t('前置条件')}}</h3><p class="test-pre-wrap">{{caseDetail.preconditions||t('无特殊前置条件')}}</p><p v-if="caseDetail.metadata?.testData" class="test-pre-wrap">{{t('测试数据')}}：{{caseDetail.metadata.testData}}</p><div class="test-table-wrap"><table class="test-table test-execution-steps"><thead><tr><th>#</th><th>{{t('操作步骤')}}</th><th>{{t('预期结果')}}</th></tr></thead><tbody><tr v-for="(step,index) in caseDetail.stepsDetail" :key="index"><td>{{index+1}}</td><td>{{step.action}}</td><td>{{step.expected}}</td></tr></tbody></table></div></template><form class="test-result-form" @submit.prevent="execute"><div class="test-section-title"><h3>{{t('记录执行结果')}}</h3><span :class="['test-badge',testTone(execution.status)]">{{t(execution.status)}}</span></div><AppSelect v-model="result.status" :options="stateOptions" :label="t('执行结果')" :disabled="saving||!writable"/><label class="test-field">{{t('实际结果')}}<textarea v-model="result.actualResult" rows="4" maxlength="20000" :disabled="saving||!writable" :required="['失败','阻塞'].includes(result.status)" :placeholder="t('记录实际观察到的结果，失败时注明具体步骤')"/></label><label class="test-field">{{t('执行备注')}}<textarea v-model="result.note" rows="2" maxlength="10000" :disabled="saving||!writable" :placeholder="t('补充环境、数据或阻塞原因')"/></label><div class="test-actions"><button class="btn primary" :disabled="saving||loading||!caseDetail||!writable">{{t('提交执行结果')}}</button><button v-if="execution.status==='失败'&&!execution.defectId" class="btn" type="button" :disabled="saving||dirty||!writable" @click="toDefect(execution)">{{t('由失败结果生成缺陷')}}</button><router-link v-if="execution.defectId" :to="`/defects?bug=${execution.defectId}`">{{t('查看关联缺陷')}} →</router-link></div></form><h3>{{t('执行历史')}}</h3><ol class="test-timeline"><li v-for="item in history" :key="item.id"><span :class="['test-badge',testTone(item.status)]">{{t(item.status)}}</span><strong>{{item.executor||t('系统')}}</strong><time>{{formatDate(item.createdAt)}}</time><p>{{item.actualResult||'—'}}</p><p v-if="item.note">{{item.note}}</p></li></ol><p v-if="!history.length" class="test-muted">{{t('尚无执行记录')}}</p><QualityComments ref="commentsPanel" :key="'execution-'+execution.id" resource="test-executions" :object-id="execution.id" :members="members" :disabled="saving"/></div></ResizableDrawer></div>
 </section>
</template>
